functions.tdTowerGoldCostForLevelBranch:
function tdTowerGoldCostForLevelBranch takes integer towerChoice, integer level, integer branch returns integer
	if level <= 1 then
		return tdTowerCost(towerChoice)
	endif
	if level >= TDConfig_TD_MAX_TOWER_LEVEL then
		return tdTowerUltimateUpgradeCost(towerChoice, branch)
	endif
	return tdTowerUpgradeCost(towerChoice, level - 1)
endfunction

functions.tdPositionIsInsideRect:
function tdPositionIsInsideRect takes real position_x, real position_y, rect area returns boolean
	return area != null and position_x >= GetRectMinX(area) and position_x <= GetRectMaxX(area) and position_y >= GetRectMinY(area) and position_y <= GetRectMaxY(area)
endfunction

